ALTER TABLE public.cms_site_config DROP CONSTRAINT IF EXISTS cms_site_config_key_check;
ALTER TABLE public.cms_site_config ADD CONSTRAINT cms_site_config_key_check CHECK (key IN ('branding','forms','home','pro','security','catalog'));
CREATE OR REPLACE FUNCTION public.cms_site_published() RETURNS TABLE(key text, published jsonb, published_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
  SELECT c.key, c.published, c.published_at FROM public.cms_site_config c WHERE c.published IS NOT NULL AND c.key IN ('branding','forms','home','pro','catalog')
$$;
GRANT EXECUTE ON FUNCTION public.cms_site_published() TO anon, authenticated, service_role;

ALTER TABLE public.contact_requests ADD COLUMN IF NOT EXISTS product text, ADD COLUMN IF NOT EXISTS department text;
CREATE INDEX IF NOT EXISTS leads_product_department ON public.contact_requests(product, department);

-- Registered department pages: drafts only, never public until an owner publishes them.
INSERT INTO public.cms_documents (path, kind, draft, state)
SELECT v.base || '/' || v.id, 'department', jsonb_build_object(
  'ar', jsonb_build_object('title', v.ar || ' | ' || v.brand, 'description', '', 'blocks', '[]'::jsonb, 'sourceEdits', '{}'::jsonb, 'headline', '', 'lede', '', 'navLabel', ''),
  'en', jsonb_build_object('title', v.en || ' | ' || v.brand, 'description', '', 'blocks', '[]'::jsonb, 'sourceEdits', '{}'::jsonb, 'headline', '', 'lede', '', 'navLabel', ''),
  'indexable', true, 'evidence', 'pending', 'formEnabled', true, 'ogImage', '', 'canonical', '',
  'department', jsonb_build_object('product', v.product, 'id', v.id, 'heroShot', '', 'heroMedia', '', 'heroAlt', jsonb_build_object('ar', '', 'en', ''), 'related', '[]'::jsonb)
), 'draft'
FROM (VALUES
('hr','/hr','DIGIT HR','core-hr','الموارد البشرية الأساسية والهيكل التنظيمي','Core HR & Organization'),
('hr','/hr','DIGIT HR','talent','المواهب والتوظيف والتطوير','Human Capital & Talent'),
('hr','/hr','DIGIT HR','workforce','الحضور والإجازات والورديات','Workforce Management'),
('hr','/hr','DIGIT HR','payroll','الرواتب والتعويضات والعمليات السعودية','Payroll, Rewards & Saudi Operations'),
('hr','/hr','DIGIT HR','self-service','الخدمة الذاتية وتجربة الموظف والمدير','Employee & Manager Experience'),
('hr','/hr','DIGIT HR','people-analytics','التحليلات وتخطيط القوى العاملة','People Intelligence & Planning'),
('hr','/hr','DIGIT HR','administration','الإعدادات والحوكمة','Administration & Governance'),
('construction','/construction','DIGIT Construction','portfolio','الإدارة والمحفظة','Management & Portfolio'),
('construction','/construction','DIGIT Construction','projects','المشاريع والتنفيذ','Projects & Execution'),
('construction','/construction','DIGIT Construction','estimating','المناقصات والتقدير وجداول الكميات','Estimating, Tendering & BOQ'),
('construction','/construction','DIGIT Construction','contracts-claims','عقود العملاء والمستخلصات','Client Contracts & Claims'),
('construction','/construction','DIGIT Construction','subcontractors','المقاولون الباطن والقياسات','Subcontractors & Measurement'),
('construction','/construction','DIGIT Construction','budget-cost','الموازنات والتكاليف والتوقعات','Budget, Cost & Forecast'),
('construction','/construction','DIGIT Construction','procurement','المشتريات والمواد','Procurement & Materials'),
('construction','/construction','DIGIT Construction','resources','الموارد والمصروفات','Resources & Spend'),
('construction','/construction','DIGIT Construction','financial-closeout','الموقف المالي والإقفال والتقارير','Financial Position, Closeout & Reports')
) AS v(product, base, brand, id, ar, en)
ON CONFLICT (path) DO NOTHING;

