      '{en}', (draft->'en') || '{"title":"Inventory & Warehouses | DIGIT Pro","description":"Serial and batch tracking, low stock alerts, and reorder suggestions — linked to Purchasing and Accounting in the same system.","headline":"Accurate Inventory in Every Warehouse… Moment by Moment","lede":"Serial and batch tracking, low stock alerts, and reorder suggestions — linked to Purchasing and Accounting in the same system.","navLabel":"","blocks":[{"id":"inv-capabilities","type":"capability","title":"No shortages… and no stagnant stock","body":"Six capabilities giving you real-time visibility of your stock across every warehouse and branch.","shotId":"","mediaUrl":"","mediaAlt":"","href":"","enabled":true,"eyebrow":"Why Digit Inventory","items":[{"title":"Reorder Point Alerts","body":"Automatic alert before item depletion with reorder suggestions.","shotId":"","href":""},{"title":"Inventory Valuation","body":"Accurate valuation methods to know your inventory value at any moment.","shotId":"","href":""},{"title":"Barcode & Batches","body":"Barcode scanning and tracking by batches and expiry dates.","shotId":"","href":""},{"title":"Inter-Warehouse Transfers","body":"Move goods between your branches with clear inventory impact.","shotId":"","href":""},{"title":"Serial Tracking","body":"Track items by serial numbers for warranty and maintenance.","shotId":"","href":""},{"title":"Movement & Aging Reports","body":"Identify fast-moving and slow-moving items for better decision-making.","shotId":"","href":""}],"shots":[],"focus":null},{"id":"inv-theater","type":"theater","title":"Inventory Dashboard… Visualized","body":"Your levels, shortages, and movements in front of you in one dashboard, across all warehouses — no scattered spreadsheets.","shotId":"","mediaUrl":"","mediaAlt":"","href":"","enabled":true,"eyebrow":"From the Inside","items":[],"shots":["07-inv-01-in1","07-inv-02-in3","07-inv-06-inv-017"],"focus":null},{"id":"inv-story-gl","type":"story","title":"Accurate inve